-- FutPulse football data model — proposal v1
-- STATUS: REVIEW ONLY. NOT APPLIED TO ANY DATABASE.
-- Target: Cloudflare D1 / SQLite. Prefix fp_ avoids collisions with 221Cloud tables.
-- IDs are generated by the application. All timestamps are UTC ISO-8601 TEXT.
-- Provider IDs are stored as TEXT to preserve their original representation.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS fp_countries (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT,
  flag_url TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(code)
);

CREATE TABLE IF NOT EXISTS fp_competitions (
  id TEXT PRIMARY KEY,
  country_id TEXT REFERENCES fp_countries(id) ON DELETE RESTRICT,
  name TEXT NOT NULL,
  competition_type TEXT,
  logo_url TEXT,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_seasons (
  id TEXT PRIMARY KEY,
  competition_id TEXT NOT NULL REFERENCES fp_competitions(id) ON DELETE RESTRICT,
  season_label TEXT NOT NULL,
  start_date TEXT,
  end_date TEXT,
  is_current INTEGER NOT NULL DEFAULT 0 CHECK (is_current IN (0,1)),
  coverage_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(coverage_json)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(competition_id, season_label)
);

CREATE TABLE IF NOT EXISTS fp_teams (
  id TEXT PRIMARY KEY,
  country_id TEXT REFERENCES fp_countries(id) ON DELETE RESTRICT,
  name TEXT NOT NULL,
  short_name TEXT,
  code TEXT,
  founded_year INTEGER,
  national INTEGER NOT NULL DEFAULT 0 CHECK (national IN (0,1)),
  logo_url TEXT,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_players (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  first_name TEXT,
  last_name TEXT,
  birth_date TEXT,
  nationality TEXT,
  height TEXT,
  weight TEXT,
  photo_url TEXT,
  position TEXT,
  preferred_foot TEXT,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_coaches (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  first_name TEXT,
  last_name TEXT,
  birth_date TEXT,
  nationality TEXT,
  photo_url TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_venues (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  address TEXT,
  city TEXT,
  country_id TEXT REFERENCES fp_countries(id) ON DELETE RESTRICT,
  capacity INTEGER,
  surface TEXT,
  image_url TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_team_memberships (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL REFERENCES fp_players(id) ON DELETE RESTRICT,
  season_id TEXT REFERENCES fp_seasons(id) ON DELETE RESTRICT,
  shirt_number INTEGER,
  position TEXT,
  started_on TEXT,
  ended_on TEXT,
  source_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(team_id, player_id, season_id, started_on)
);

CREATE TABLE IF NOT EXISTS fp_coach_assignments (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  coach_id TEXT NOT NULL REFERENCES fp_coaches(id) ON DELETE RESTRICT,
  season_id TEXT REFERENCES fp_seasons(id) ON DELETE RESTRICT,
  role TEXT,
  started_on TEXT,
  ended_on TEXT,
  source_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(team_id, coach_id, season_id, started_on)
);

CREATE TABLE IF NOT EXISTS fp_fixtures (
  id TEXT PRIMARY KEY,
  competition_id TEXT NOT NULL REFERENCES fp_competitions(id) ON DELETE RESTRICT,
  season_id TEXT NOT NULL REFERENCES fp_seasons(id) ON DELETE RESTRICT,
  home_team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  away_team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  venue_id TEXT REFERENCES fp_venues(id) ON DELETE SET NULL,
  kickoff_at TEXT,
  timezone TEXT,
  status_short TEXT NOT NULL DEFAULT 'NS',
  status_long TEXT,
  elapsed_minutes INTEGER,
  round_name TEXT,
  stage TEXT,
  referee TEXT,
  home_goals INTEGER,
  away_goals INTEGER,
  halftime_home_goals INTEGER,
  halftime_away_goals INTEGER,
  fulltime_home_goals INTEGER,
  fulltime_away_goals INTEGER,
  extratime_home_goals INTEGER,
  extratime_away_goals INTEGER,
  penalty_home_goals INTEGER,
  penalty_away_goals INTEGER,
  is_neutral_venue INTEGER NOT NULL DEFAULT 0 CHECK (is_neutral_venue IN (0,1)),
  postponed INTEGER NOT NULL DEFAULT 0 CHECK (postponed IN (0,1)),
  source_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(home_team_id <> away_team_id)
);

CREATE TABLE IF NOT EXISTS fp_fixture_events (
  id TEXT PRIMARY KEY,
  fixture_id TEXT NOT NULL REFERENCES fp_fixtures(id) ON DELETE RESTRICT,
  event_order INTEGER NOT NULL,
  elapsed_minutes INTEGER,
  extra_minutes INTEGER,
  team_id TEXT REFERENCES fp_teams(id) ON DELETE SET NULL,
  player_id TEXT REFERENCES fp_players(id) ON DELETE SET NULL,
  assist_player_id TEXT REFERENCES fp_players(id) ON DELETE SET NULL,
  event_type TEXT NOT NULL,
  detail TEXT,
  comments TEXT,
  provider_event_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(fixture_id, event_order)
);

CREATE TABLE IF NOT EXISTS fp_fixture_lineups (
  id TEXT PRIMARY KEY,
  fixture_id TEXT NOT NULL REFERENCES fp_fixtures(id) ON DELETE RESTRICT,
  team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  coach_id TEXT REFERENCES fp_coaches(id) ON DELETE SET NULL,
  formation TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(fixture_id, team_id)
);

CREATE TABLE IF NOT EXISTS fp_fixture_lineup_players (
  id TEXT PRIMARY KEY,
  lineup_id TEXT NOT NULL REFERENCES fp_fixture_lineups(id) ON DELETE RESTRICT,
  player_id TEXT REFERENCES fp_players(id) ON DELETE SET NULL,
  player_name_snapshot TEXT,
  shirt_number INTEGER,
  position TEXT,
  grid_position TEXT,
  is_starting INTEGER NOT NULL DEFAULT 0 CHECK (is_starting IN (0,1)),
  is_captain INTEGER NOT NULL DEFAULT 0 CHECK (is_captain IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(player_id IS NOT NULL OR player_name_snapshot IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS fp_standings_snapshots (
  id TEXT PRIMARY KEY,
  competition_id TEXT NOT NULL REFERENCES fp_competitions(id) ON DELETE RESTRICT,
  season_id TEXT NOT NULL REFERENCES fp_seasons(id) ON DELETE RESTRICT,
  group_name TEXT,
  captured_at TEXT NOT NULL,
  provider_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_standing_rows (
  id TEXT PRIMARY KEY,
  snapshot_id TEXT NOT NULL REFERENCES fp_standings_snapshots(id) ON DELETE RESTRICT,
  team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  rank_position INTEGER,
  points INTEGER,
  played INTEGER,
  wins INTEGER,
  draws INTEGER,
  losses INTEGER,
  goals_for INTEGER,
  goals_against INTEGER,
  goal_difference INTEGER,
  form TEXT,
  description TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(snapshot_id, team_id)
);

CREATE TABLE IF NOT EXISTS fp_player_season_stats (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES fp_players(id) ON DELETE RESTRICT,
  team_id TEXT REFERENCES fp_teams(id) ON DELETE SET NULL,
  competition_id TEXT NOT NULL REFERENCES fp_competitions(id) ON DELETE RESTRICT,
  season_id TEXT NOT NULL REFERENCES fp_seasons(id) ON DELETE RESTRICT,
  appearances INTEGER,
  starts INTEGER,
  minutes_played INTEGER,
  goals INTEGER,
  assists INTEGER,
  clean_sheets INTEGER,
  saves INTEGER,
  goals_conceded INTEGER,
  rating REAL,
  stats_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(stats_json)),
  source_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(player_id, team_id, competition_id, season_id)
);

CREATE TABLE IF NOT EXISTS fp_fixture_team_stats (
  id TEXT PRIMARY KEY,
  fixture_id TEXT NOT NULL REFERENCES fp_fixtures(id) ON DELETE RESTRICT,
  team_id TEXT NOT NULL REFERENCES fp_teams(id) ON DELETE RESTRICT,
  stats_json TEXT NOT NULL CHECK (json_valid(stats_json)),
  source_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(fixture_id, team_id)
);

CREATE TABLE IF NOT EXISTS fp_fixture_player_stats (
  id TEXT PRIMARY KEY,
  fixture_id TEXT NOT NULL REFERENCES fp_fixtures(id) ON DELETE RESTRICT,
  team_id TEXT REFERENCES fp_teams(id) ON DELETE SET NULL,
  player_id TEXT REFERENCES fp_players(id) ON DELETE SET NULL,
  player_name_snapshot TEXT,
  minutes_played INTEGER,
  rating REAL,
  stats_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(stats_json)),
  source_updated_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(player_id IS NOT NULL OR player_name_snapshot IS NOT NULL)
);

-- Provider IDs are kept outside canonical records so multiple providers can map
-- to the same FutPulse entity. scope_key must be '' when no scope is applicable.
CREATE TABLE IF NOT EXISTS fp_provider_entity_mappings (
  id TEXT PRIMARY KEY,
  provider_code TEXT NOT NULL,
  entity_type TEXT NOT NULL CHECK (entity_type IN (
    'country','competition','season','team','player','coach','venue','fixture'
  )),
  provider_entity_id TEXT NOT NULL,
  scope_key TEXT NOT NULL DEFAULT '',
  canonical_entity_id TEXT NOT NULL,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)),
  last_seen_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(provider_code, entity_type, provider_entity_id, scope_key)
);

CREATE TABLE IF NOT EXISTS fp_provider_sync_state (
  id TEXT PRIMARY KEY,
  provider_code TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  scope_key TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','running','success','partial','failed','disabled')),
  last_attempt_at TEXT,
  last_success_at TEXT,
  next_run_at TEXT,
  records_received INTEGER NOT NULL DEFAULT 0,
  records_created INTEGER NOT NULL DEFAULT 0,
  records_updated INTEGER NOT NULL DEFAULT 0,
  error_code TEXT,
  error_message TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(provider_code, endpoint, scope_key)
);

CREATE TABLE IF NOT EXISTS fp_provider_raw_payloads (
  id TEXT PRIMARY KEY,
  provider_code TEXT NOT NULL,
  endpoint TEXT NOT NULL,
  scope_key TEXT NOT NULL DEFAULT '',
  fetched_at TEXT NOT NULL,
  http_status INTEGER,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  content_hash TEXT,
  related_entity_type TEXT,
  related_entity_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS fp_data_conflicts (
  id TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL,
  canonical_entity_id TEXT NOT NULL,
  field_name TEXT NOT NULL,
  provider_values_json TEXT NOT NULL CHECK (json_valid(provider_values_json)),
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open','resolved','ignored')),
  resolution_note TEXT,
  detected_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at TEXT
);

CREATE INDEX IF NOT EXISTS idx_fp_competitions_country ON fp_competitions(country_id);
CREATE INDEX IF NOT EXISTS idx_fp_seasons_competition ON fp_seasons(competition_id, is_current);
CREATE INDEX IF NOT EXISTS idx_fp_teams_country ON fp_teams(country_id);
CREATE INDEX IF NOT EXISTS idx_fp_memberships_team_season ON fp_team_memberships(team_id, season_id);
CREATE INDEX IF NOT EXISTS idx_fp_memberships_player ON fp_team_memberships(player_id);
CREATE INDEX IF NOT EXISTS idx_fp_coach_assignments_team ON fp_coach_assignments(team_id, season_id);
CREATE INDEX IF NOT EXISTS idx_fp_fixtures_kickoff ON fp_fixtures(kickoff_at);
CREATE INDEX IF NOT EXISTS idx_fp_fixtures_competition_season_date ON fp_fixtures(competition_id, season_id, kickoff_at);
CREATE INDEX IF NOT EXISTS idx_fp_fixtures_home_date ON fp_fixtures(home_team_id, kickoff_at);
CREATE INDEX IF NOT EXISTS idx_fp_fixtures_away_date ON fp_fixtures(away_team_id, kickoff_at);
CREATE INDEX IF NOT EXISTS idx_fp_fixtures_status_date ON fp_fixtures(status_short, kickoff_at);
CREATE INDEX IF NOT EXISTS idx_fp_events_fixture_order ON fp_fixture_events(fixture_id, event_order);
CREATE INDEX IF NOT EXISTS idx_fp_lineup_players_lineup ON fp_fixture_lineup_players(lineup_id);
CREATE INDEX IF NOT EXISTS idx_fp_standings_competition_season ON fp_standings_snapshots(competition_id, season_id, captured_at);
CREATE INDEX IF NOT EXISTS idx_fp_standing_rows_snapshot_rank ON fp_standing_rows(snapshot_id, rank_position);
CREATE INDEX IF NOT EXISTS idx_fp_player_stats_player_season ON fp_player_season_stats(player_id, season_id);
CREATE INDEX IF NOT EXISTS idx_fp_fixture_player_stats_fixture ON fp_fixture_player_stats(fixture_id);
CREATE INDEX IF NOT EXISTS idx_fp_provider_mappings_canonical ON fp_provider_entity_mappings(entity_type, canonical_entity_id);
CREATE INDEX IF NOT EXISTS idx_fp_sync_due ON fp_provider_sync_state(status, next_run_at);
CREATE INDEX IF NOT EXISTS idx_fp_raw_payloads_provider_date ON fp_provider_raw_payloads(provider_code, fetched_at);
CREATE INDEX IF NOT EXISTS idx_fp_conflicts_status_date ON fp_data_conflicts(status, detected_at);
